mapper.select:
/* TbmAi01Mapper.selectMtrlCdByItemCd */
SELECT A.MTRL_CD
FROM TB_TBM_EDU_MTRL_ITEM A
	 INNER JOIN TB_TBM_EDU_MTRL M
	 	ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}
LIMIT 1

/* TbmAi01Mapper.selectMtrlSiteScope */
SELECT
	MTRL_CD		AS mtrlCd
	, SITE_CD	AS siteCd
FROM TB_TBM_EDU_MTRL
WHERE MTRL_CD = #{mtrlCd}
  AND CMPNY_CD = #{gvCmpnyCd}
  AND USE_YN = 'Y'

/* TbmAi01Mapper.countUserSiteAuth */
SELECT
	COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

mapper.update:
/* TbmAi01Mapper.markItemsAnalyzing */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_STATUS	= 'ANALYZING'
	, A.UPDATE_NO	= #{userCd}
	, A.UPDATE_DATE	= NOW()
/* 테넌트 격리: 항목 자신의 CMPNY_CD 로 함께 좁힌다(MTRL_CD 는 회사별 채번). */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_CD = #{mtrlCd}
  AND A.USE_YN = 'Y'
  AND A.AI_ANALYZE_YN = 'Y'                 /* ★v4 추가 */
  AND A.MTRL_ITEM_TYPE IN ('01','04')
  AND (A.AI_STATUS IS NULL OR A.AI_STATUS IN ('NONE','FAILED','DRAFT'))

/* TbmAi01Mapper.markItemsAnalyzingAuto */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_STATUS	= 'ANALYZING'
	, A.UPDATE_NO	= #{userCd}
	, A.UPDATE_DATE	= NOW()
/* 테넌트 격리: 항목 자신의 CMPNY_CD 로 함께 좁힌다(MTRL_CD 는 회사별 채번). */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_CD = #{mtrlCd}
  AND A.USE_YN = 'Y'
  AND A.AI_ANALYZE_YN = 'Y'
  AND A.MTRL_ITEM_TYPE IN ('01','04')
  AND (A.AI_STATUS IS NULL OR A.AI_STATUS IN ('NONE','FAILED'))

/* TbmAi01Mapper.markItemAnalyzing */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_STATUS	= 'ANALYZING'
	, A.UPDATE_NO	= #{userCd}
	, A.UPDATE_DATE	= NOW()
/* 테넌트 격리: MTRL_ITEM_CD 는 회사별 채번이라 전역 유일하지 않다. 항목 자신의 CMPNY_CD 필수. */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}

/* TbmAi01Mapper.updateItemDraft */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_STATUS			= 'DRAFT'
	, A.AI_DRAFT_TEXT	= #{draftText}
	, A.AI_CHAT_JSON	= #{chatJson}
	, A.AI_ANALYZED_AT	= NOW()
	, A.UPDATE_NO		= #{userCd}
	, A.UPDATE_DATE		= NOW()
/* 테넌트 격리: 항목 자신의 CMPNY_CD 필수(MTRL_ITEM_CD 는 회사별 채번). */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}

/* TbmAi01Mapper.updateItemFailed */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_STATUS			= 'FAILED'
	, A.AI_ANALYZED_AT	= NOW()
	, A.UPDATE_NO		= #{userCd}
	, A.UPDATE_DATE		= NOW()
/* 테넌트 격리: 항목 자신의 CMPNY_CD 필수(MTRL_ITEM_CD 는 회사별 채번). */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}

/* TbmAi01Mapper.updateItemChatJson */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_CHAT_JSON	= #{chatJson}
	, A.UPDATE_NO	= #{userCd}
	, A.UPDATE_DATE	= NOW()
/* 테넌트 격리: 항목 자신의 CMPNY_CD 필수(MTRL_ITEM_CD 는 회사별 채번). */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}

/* TbmAi01Mapper.updateItemConfirm */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	   INNER JOIN TB_TBM_EDU_MTRL M
	   	  ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET
	A.AI_CONFIRM_DESC	= #{confirmDesc}
	, A.AI_STATUS		= 'CONFIRMED'
	, A.UPDATE_NO		= #{userCd}
	, A.UPDATE_DATE		= NOW()
/* 테넌트 격리: 항목 자신의 CMPNY_CD 필수(MTRL_ITEM_CD 는 회사별 채번). */
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}

mapper.sql:
WHERE M.CMPNY_CD = #{gvCmpnyCd}

  AND A.CMPNY_CD = #{gvCmpnyCd}
  AND M.USE_YN = 'Y'
  AND A.USE_YN = 'Y'
  /* AI 분석 관리 화면은 '분석 지정된' 항목만 다룬다.
     지정 해제(N) 항목은 관리 대상이 아니므로 목록/총건수 양쪽에서 제외한다. */
  AND A.AI_ANALYZE_YN = 'Y'
  /* ★사업장 격리: assertSiteAccess 동치.
     - 회사공통 행(SITE_CD 비어있음): canManageCommon 일 때만 노출
     - 사업장 행: companyWide 통과, 아니면 TB_USER_SITE_AUTH 매핑 보유 사업장만 */
  AND (
	( (M.SITE_CD IS NULL OR M.SITE_CD = '')
	   AND 1 = 0 
	)
	OR
	( (M.SITE_CD IS NOT NULL AND M.SITE_CD <> '')

		AND M.SITE_CD IN (
			SELECT UA.SITE_CD
			FROM TB_USER_SITE_AUTH UA
			WHERE UA.CMPNY_CD = #{gvCmpnyCd}
			  AND UA.USER_CD = #{gvUserCd}
			  AND UA.USE_YN = 'Y'
		)

	)
  )
  /* 필터(선택) */


	   AND (M.SITE_CD IS NULL OR M.SITE_CD = '') 
	   AND M.SITE_CD = #{siteCd} 


   AND A.MTRL_ITEM_TYPE = #{mtrlItemType} 




		AND IFNULL(A.AI_STATUS, 'NONE') = 'NONE'
		AND A.MTRL_ITEM_TYPE IN ('01', '04')


		AND IFNULL(A.AI_STATUS, 'NONE') = 'NONE'
		AND A.MTRL_ITEM_TYPE IN ('02', '03')

	   AND A.AI_STATUS = #{aiStatus} 





	AND ( M.TITLE LIKE CONCAT('%', #{safeKeyword}, '%') ESCAPE '\'
	   OR A.MTRL_DESC LIKE CONCAT('%', #{safeKeyword}, '%') ESCAPE '\' )




	AND EXISTS (
		SELECT 1
		FROM TB_FILE_INFO F
		WHERE F.CMPNY_CD = M.CMPNY_CD
		  AND F.FILE_MGMT_CD = A.FILE_MGMT_CD
		  AND F.FILE_NM LIKE CONCAT('%', #{safeFileNm}, '%') ESCAPE '\'
	)

mapper.select:
/* TbmAi01Mapper.selectAnalysisWorklist */ SELECT M.MTRL_CD AS mtrlCd , M.TITLE AS title , M.SITE_CD AS siteCd , A.MTRL_ITEM_CD AS mtrlItemCd , A.MTRL_ITEM_TYPE AS mtrlItemType , A.MTRL_DESC AS mtrlDesc , A.AI_ANALYZE_YN AS aiAnalyzeYn , A.AI_STATUS AS aiStatus , CASE WHEN TRIM(IFNULL(A.AI_CONFIRM_DESC, '')) <> '' THEN 'Y' ELSE 'N' END AS hasConfirmDesc , A.FILE_MGMT_CD AS fileMgmtCd , B.FILE_NM AS fileNm , B.FILE_PATH AS filePath , B.FILE_EXT AS fileExt , A.URL AS url , A.THUMB_FILE_MGMT_CD AS thumbFileMgmtCd , A.DURATION_SEC AS durationSec , DATE_FORMAT(A.AI_ANALYZED_AT, '%Y-%m-%d %H:%i') AS aiAnalyzedAt FROM TB_TBM_EDU_MTRL_ITEM A INNER JOIN TB_TBM_EDU_MTRL M
ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD) /* TB_FILE_INFO PK = CMPNY_CD + FILE_MGMT_CD. 회사 조건이 빠지면 타 회사 동일 코드 행이 붙어 파일명이 뒤바뀌거나 행이 늘어난다(총건수 쿼리와 불일치). */ LEFT OUTER JOIN TB_FILE_INFO B ON (B.CMPNY_CD = M.CMPNY_CD AND B.FILE_MGMT_CD = A.FILE_MGMT_CD)
/* 회사공통(SITE_CD 없음) 자료를 항상 맨 위로 — 페이징(LIMIT/OFFSET)에서도 1페이지에 모이도록. FE 는 이 순서대로 mtrlCd 로 그룹핑하므로(Map 삽입순) 회사공통 그룹이 상단에 온다. SORT_IDX 는 자료 안에서 중복될 수 있어(동점) 마지막에 MTRL_ITEM_CD 로 순서를 확정한다 — 동점이 남으면 LIMIT/OFFSET 페이지 경계에서 행이 중복/누락될 수 있다. */ ORDER BY (M.SITE_CD IS NULL OR M.SITE_CD = '') DESC , M.MTRL_CD , A.SORT_IDX , A.MTRL_ITEM_CD LIMIT #{limit} OFFSET #{offset}
